      _kotlinIntTable('UmmAlQuraTable', kUmmAlQuraTable));
  _write(dir, 'infrastructure/calendar/data/DiyanetTable.kt',
      _kotlinIntTable('DiyanetTable', kDiyanetTable));
  _write(dir, 'infrastructure/calendar/data/HijriHolidays.kt', _kotlinHolidays());
  _write(dir, 'infrastructure/calendar/data/HijriSightings.kt',
      _kotlinSightings());
  _write(dir, 'infrastructure/geocoding/data/CityDataset.kt',
