String _kotlinIntTable(String typeName, List<int> data) => '''
$_header
package $_kotlinPackage.infrastructure.calendar.data

/**
 * Modified Chronological Julian Day Number (CJDN − 2,400,000) of the first day
 * of each lunar month, one entry per lunation. ${data.length} entries.
 */
internal object $typeName {
    @JvmField
    val data: IntArray = intArrayOf(
${_intRows(data, indent: '        ')}    )
}
''';

String _kotlinHolidays() {
  final buffer = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln('package $_kotlinPackage.infrastructure.calendar.data')
    ..writeln()
    ..writeln('/** Islamic holidays keyed by Hijri month, then day. */')
    ..writeln('internal object HijriHolidays {')
    ..writeln('    @JvmField')
    ..writeln('    val byMonth: Map<Int, Map<Int, List<String>>> = mapOf(');
  for (final month in kHijriHolidays.entries) {
    buffer.writeln('        ${month.key} to mapOf(');
    for (final day in month.value.entries) {
      buffer.writeln(
          '            ${day.key} to listOf(${day.value.map(_kotlinStr).join(', ')}),');
    }
    buffer.writeln('        ),');
  }
  buffer
    ..writeln('    )')
    ..writeln('}');
  return buffer.toString();
}

String _kotlinSightings() {
  final buffer = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln('package $_kotlinPackage.infrastructure.calendar.data')
    ..writeln()
    ..writeln('/**')
    ..writeln(' * HJCoSA announced lunar-sighting overrides: Gregorian `dd-mm-yyyy` ->')
    ..writeln(' * announced Hijri `dd-mm-yyyy`.')
    ..writeln(' */')
    ..writeln('internal object HijriSightings {')
    ..writeln('    @JvmField')
    ..writeln('    val gregorianToHijri: Map<String, String> = linkedMapOf(');
  for (final e in kHjcosaSightings.entries) {
    buffer.writeln('        ${_kotlinStr(e.key)} to ${_kotlinStr(e.value)},');
  }
  buffer
    ..writeln('    )')
    ..writeln()
    ..writeln('    /** The inverse map (all announced values are distinct). */')
    ..writeln('    @JvmField')
    ..writeln('    val hijriToGregorian: Map<String, String> =')
    ..writeln('        gregorianToHijri.entries.associate { (gregorian, hijri) -> hijri to gregorian }')
    ..writeln('}');
  return buffer.toString();
}

String _kotlinCityDataset() {
  final buffer = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln('package $_kotlinPackage.infrastructure.geocoding.data')
    ..writeln()
    ..writeln('/**')
    ..writeln(' * A curated city record: name, ISO-3166 alpha-2 country, optional state,')
    ..writeln(' * coordinates and the city\'s **standard-time** UTC offset in minutes.')
    ..writeln(' */')
    ..writeln('data class CityRecord(')
    ..writeln('    val name: String,')
    ..writeln('    val country: String,')
    ..writeln('    val state: String?,')
    ..writeln('    val lat: Double,')
    ..writeln('    val lng: Double,')
    ..writeln('    val offsetMinutes: Int,')
    ..writeln(')')
    ..writeln()
    ..writeln('/** The curated, offline city set behind `BundledCityGeocoder`. */')
    ..writeln('object CityDataset {')
    ..writeln('    /** ${kCityDataset.length} major world cities (capitals + large cities). */')
    ..writeln('    @JvmField')
    ..writeln('    val records: List<CityRecord> = listOf(');
  for (final r in kCityDataset) {
    final state = r.state == null ? 'null' : _kotlinStr(r.state!);
    buffer.writeln(
        '        CityRecord(${_kotlinStr(r.name)}, ${_kotlinStr(r.country)}, $state, ${r.lat}, ${r.lng}, ${r.offsetMinutes}),');
  }
  buffer
    ..writeln('    )')
    ..writeln()
    ..writeln('    /** Lower-case common country names -> ISO-3166 alpha-2 codes. */')
    ..writeln('    @JvmField')
    ..writeln('    val countryAliases: Map<String, String> = linkedMapOf(');
  for (final e in kCountryAliases.entries) {
    buffer.writeln('        ${_kotlinStr(e.key)} to ${_kotlinStr(e.value)},');
  }
  buffer
    ..writeln('    )')
    ..writeln('}');
  return buffer.toString();
}

String _kotlinCountryIsoMap() {
  final buffer = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln('package $_kotlinPackage.infrastructure.geocoding.data')
    ..writeln()
    ..writeln('/** The bundled database\'s integer `country_id` <-> ISO 3166-1 alpha-2 mapping. */')
    ..writeln('object CountryIsoMap {')
    ..writeln('    /** ${kCountryIdToIso.length} entries; id 103 is absent in the database. */')
    ..writeln('    @JvmField')
    ..writeln('    val idToIso: Map<Int, String> = linkedMapOf(');
  for (final e in kCountryIdToIso.entries) {
    buffer.writeln('        ${e.key} to ${_kotlinStr(e.value)},');
  }
  buffer
    ..writeln('    )')
    ..writeln()
    ..writeln('    /** The inverse of [idToIso]. */')
    ..writeln('    @JvmField')
    ..writeln('    val isoToId: Map<String, Int> = idToIso.entries.associate { (id, iso) -> iso to id }')
    ..writeln()
    ..writeln('    /**')
    ..writeln('     * Time zones whose standard offset is not a whole hour. The database stores')
    ..writeln('     * whole hours, so these override the stored value (in minutes).')
    ..writeln('     */')
    ..writeln('    @JvmField')
    ..writeln('    val fractionalZoneOffsetMinutes: Map<String, Int> = linkedMapOf(');
  for (final e in kFractionalZoneOffsetMinutes.entries) {
    buffer.writeln('        ${_kotlinStr(e.key)} to ${e.value},');
  }
  buffer
    ..writeln('    )')
    ..writeln('}');
  return buffer.toString();
}

String _kotlinLocalizedTable(String name, String doc, Map<int, LocalizedName> table) {
  final buffer = StringBuffer()
    ..writeln('    /** $doc */')
    ..writeln('    @JvmField')
    ..writeln('    val $name: Map<Int, LocalizedName> = linkedMapOf(');
  for (final e in table.entries) {
    buffer.writeln(
        '        ${e.key} to LocalizedName(${_kotlinStr(e.value.en)}, ${_kotlinStr(e.value.ar)}),');
  }
  buffer.writeln('    )');
  return buffer.toString();
}

String _kotlinLocalizer() {
  final buffer = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln('package $_kotlinPackage.infrastructure.localization')
    ..writeln()
    ..writeln('/** A localized (English + Arabic) name pair. */')
    ..writeln('data class LocalizedName(val en: String, val ar: String)')
    ..writeln()
    ..writeln('/**')
    ..writeln(' * Static English/Arabic name tables for Gregorian and Hijri calendars.')
    ..writeln(' *')
    ..writeln(' * Weekdays are keyed by ISO weekday number (Mon = 1 … Sun = 7).')
    ..writeln(' */')
    ..writeln('object Localizer {')
    ..write(_kotlinLocalizedTable('islamicMonths', 'Hijri months 1..12.', Localizer.islamicMonths))
    ..writeln()
    ..write(_kotlinLocalizedTable('hijriWeekdays', 'Hijri weekday names keyed by ISO weekday (Mon = 1 … Sun = 7).', Localizer.hijriWeekdays))
    ..writeln()
    ..write(_kotlinLocalizedTable('gregorianMonths', 'Gregorian months 1..12.', Localizer.gregorianMonths))
    ..writeln()
    ..write(_kotlinLocalizedTable('gregorianWeekdays', 'Gregorian weekday names keyed by ISO weekday (Mon = 1 … Sun = 7).', Localizer.gregorianWeekdays))
    ..writeln()
    ..writeln('    /** English three-letter month abbreviations, index 0 = January. */')
    ..writeln('    @JvmField')
    ..writeln('    val monthAbbrEn: List<String> = listOf(${Localizer.monthAbbrEn.map(_kotlinStr).join(', ')})')
    ..writeln()
    ..writeln('    /** Hijri weekday name for an ISO weekday (Mon = 1 … Sun = 7). */')
    ..writeln('    @JvmStatic')
    ..writeln('    fun hijriWeekday(isoWeekday: Int): LocalizedName = hijriWeekdays.getValue(isoWeekday)')
    ..writeln()
    ..writeln('    /** Gregorian weekday name for an ISO weekday (Mon = 1 … Sun = 7). */')
    ..writeln('    @JvmStatic')
    ..writeln('    fun gregorianWeekday(isoWeekday: Int): LocalizedName = gregorianWeekdays.getValue(isoWeekday)')
    ..writeln('}');
  return buffer.toString();
}

String _kotlinMethodParams(MethodParams p) {
  final args = <String>['fajrAngle = ${p.fajrAngle}'];
  if (p.ishaAngle != null) args.add('ishaAngle = ${p.ishaAngle}');
  if (p.ishaMinutesAfterMaghrib != null) {
    args.add('ishaMinutesAfterMaghrib = ${p.ishaMinutesAfterMaghrib}');
  }
  if (p.ramadanIshaMinutesAfterMaghrib != null) {
    args.add(
        'ramadanIshaMinutesAfterMaghrib = ${p.ramadanIshaMinutesAfterMaghrib}');
  }
  if (p.maghribAngle != null) args.add('maghribAngle = ${p.maghribAngle}');
  if (p.maghribMinutesAfterSunset != null) {
    args.add('maghribMinutesAfterSunset = ${p.maghribMinutesAfterSunset}');
  }
  if (!p.adjustments.isEmpty) {
    final a = p.adjustments;
    final fields = <String>[
      if (a.fajr != 0) 'fajr = ${a.fajr}',
      if (a.sunrise != 0) 'sunrise = ${a.sunrise}',
      if (a.dhuhr != 0) 'dhuhr = ${a.dhuhr}',
      if (a.asr != 0) 'asr = ${a.asr}',
      if (a.maghrib != 0) 'maghrib = ${a.maghrib}',
      if (a.isha != 0) 'isha = ${a.isha}',
    ];
    args.add('adjustments = MethodAdjustments(${fields.join(', ')})');
  }
  if (p.midnightMode != null) {
    args.add('midnightMode = MidnightMode.${_upperSnake(p.midnightMode!.name)}');
  }
  if (p.location != null) {
    args.add(
        'location = Coordinates(${p.location!.latitude}, ${p.location!.longitude})');
  }
  return 'MethodParams(${args.join(', ')})';
}

String _kotlinCalculationMethod() {
  final buffer = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln('package $_kotlinPackage.domain.enums')
    ..writeln()
    ..writeln('import $_kotlinPackage.domain.valueobjects.Coordinates')
    ..writeln('import $_kotlinPackage.domain.valueobjects.MethodAdjustments')
    ..writeln('import $_kotlinPackage.domain.valueobjects.MethodParams')
    ..writeln()
    ..writeln('/**')
    ..writeln(' * A prayer-time calculation method (twilight authority).')
    ..writeln(' *')
    ..writeln(' * Each method carries its numeric [id] and short [code], a human-readable')
    ..writeln(' * [methodName], and its strongly-typed [params]. Methods with ids 1–23 keep the')
    ..writeln(' * numbering of the aladhan API; the regional authorities aladhan does not')
    ..writeln(' * publish are numbered from 101 so the two id spaces never collide. Entries are')
    ..writeln(' * declared in the Dart package\'s order, so [entries] matches')
    ..writeln(' * `CalculationMethod.values`.')
    ..writeln(' */')
    ..writeln('enum class CalculationMethod(')
    ..writeln('    /** Numeric id (aladhan id for ids <= 99). */')
    ..writeln('    val id: Int,')
    ..writeln('    /** Short upper-case code, e.g. `"MWL"`. */')
    ..writeln('    val code: String,')
    ..writeln('    /** Human-readable authority name. */')
    ..writeln('    val methodName: String,')
    ..writeln('    /** The method\'s twilight parameters and published corrections. */')
    ..writeln('    val params: MethodParams,')
    ..writeln('    /** Whether Fajr/Isha are bounded by the Moonsighting Committee twilight. */')
    ..writeln('    val usesMoonsighting: Boolean = false,')
    ..writeln(') : Localized {');
  const methods = CalculationMethod.values;
  for (var i = 0; i < methods.length; i++) {
    final m = methods[i];
    final args = <String>[
      '${m.id}',
      _kotlinStr(m.code),
      _kotlinStr(m.methodName),
      _kotlinMethodParams(m.params),
      if (m.usesMoonsighting) 'usesMoonsighting = true',
    ];
    final terminator = i == methods.length - 1 ? ';' : ',';
    buffer
      ..writeln('    ${_upperSnake(m.name)}(')
      ..writeln('        ${args.join(',\n        ')},')
      ..writeln('    )$terminator');
  }
  buffer
    ..writeln()
    ..writeln('    /** Whether [id] is an aladhan method id (ids above 99 are package extensions). */')
    ..writeln('    val isAladhanMethod: Boolean')
    ..writeln('        get() = id <= 99')
    ..writeln()
    ..writeln('    override fun title(language: Language): String = when (this) {');
  for (final m in methods) {
    buffer.writeln(
        '        ${_upperSnake(m.name)} -> if (language == Language.AR) ${_kotlinStr(m.title(Language.ar))} else ${_kotlinStr(m.title(Language.en))}');
  }
  buffer
    ..writeln('    }')
    ..writeln()
    ..writeln('    override fun description(language: Language): String = when (this) {');
  for (final m in methods) {
    buffer.writeln(
        '        ${_upperSnake(m.name)} -> if (language == Language.AR) ${_kotlinStr(m.description(Language.ar))} else ${_kotlinStr(m.description(Language.en))}');
  }
  buffer
    ..writeln('    }')
    ..writeln()
    ..writeln('    companion object {')
    ..writeln('        /** Looks a method up by id, falling back to [MWL]. */')
    ..writeln('        @JvmStatic')
    ..writeln('        fun fromId(id: Int): CalculationMethod = entries.firstOrNull { it.id == id } ?: MWL')
    ..writeln()
    ..writeln('        /** Looks a method up by code, falling back to [MWL]. */')
    ..writeln('        @JvmStatic')
    ..writeln('        fun fromCode(code: String): CalculationMethod = entries.firstOrNull { it.code == code } ?: MWL')
    ..writeln('    }')
    ..writeln('}');
  return buffer.toString();
}

String _kotlinEnumStrings() {
  final buffer = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln('package $_kotlinPackage.domain.enums')
    ..writeln()
    ..writeln('/**')
    ..writeln(' * End-user localization (title + description) for every enum except')
    ..writeln(' * [CalculationMethod], which carries its own. Enums delegate their')
    ..writeln(' * [Localized] members here.')
    ..writeln(' */')
    ..writeln('internal object EnumStrings {');
  var first = true;
  for (final e in _localizedEnums()) {
    if (!first) buffer.writeln();
    first = false;
    buffer.writeln('    fun title(value: ${e.typeName}, language: Language): String = when (value) {');
    for (final v in e.values) {
      buffer.writeln(
          '        ${e.typeName}.${_upperSnake(v.dartName)} -> if (language == Language.AR) ${_kotlinStr(v.titleAr)} else ${_kotlinStr(v.titleEn)}');
    }
    buffer
      ..writeln('    }')
      ..writeln()
      ..writeln('    fun description(value: ${e.typeName}, language: Language): String = when (value) {');
    for (final v in e.values) {
      buffer.writeln(
          '        ${e.typeName}.${_upperSnake(v.dartName)} -> if (language == Language.AR) ${_kotlinStr(v.descAr)} else ${_kotlinStr(v.descEn)}');
    }
    buffer.writeln('    }');
  }
  buffer.writeln('}');
  return buffer.toString();
}
